import sys,numpy as np,mujoco
from scipy.spatial.transform import Rotation
sys.path.insert(0,'/opt/tools');import casa_tool
s=casa_tool.Session('/app/instance.npz');m=s.model;d=s.data;site=mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_SITE,'gripper0_right_grip_site')
js=[m.joint(f'robot0_joint{i}').id for i in range(1,8)];qa=np.array([m.jnt_qposadr[j] for j in js]);da=np.array([m.jnt_dofadr[j] for j in js]);ranges=np.array([m.jnt_range[j] for j in js]);x=mujoco.MjData(m);x.qpos[:]=d.qpos;mujoco.mj_forward(m,x);R0=x.site_xmat[site].reshape(3,3).copy();q=x.qpos[qa].copy();p0=x.site_xpos[site].copy();cap=mujoco.mj_name2id(m,mujoco.mjtObj.mjOBJ_GEOM,'stand_mixer_island_group_g37');cp=x.geom_xpos[cap].copy();cr=x.geom_xmat[cap].reshape(3,3);n=-cr[:,1];surf=cp+m.geom_size[cap,0]*n
seq=[];lift=np.array([p0[0],p0[1],1.62]);above=np.array([cp[0],cp[1],1.60]);
for u in np.linspace(0,1,44):seq.append(p0+(lift-p0)*u)
for u in np.linspace(0,1,60):seq.append(lift+(above-lift)*u)
pre=surf+.074*n
for u in np.linspace(0,1,36):seq.append(above+(pre-above)*u)
checks=[0,10,20,30,43,44,55,70,85,103,104,115,125,139]
for ix,t in enumerate(seq):
 for it in range(100):
  x.qpos[:]=d.qpos;x.qpos[qa]=q;mujoco.mj_forward(m,x);ep=t-x.site_xpos[site];R=x.site_xmat[site].reshape(3,3);er=Rotation.from_matrix(R0@R.T).as_rotvec();e=np.r_[ep,.35*er];jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));mujoco.mj_jacSite(m,x,jp,jr,site);J=np.vstack([jp[:,da],.35*jr[:,da]]);dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,e);nn=np.linalg.norm(dq);dq*=min(1,.1/nn);q+=dq
  if np.linalg.norm(ep)<.0008 and np.linalg.norm(er)<.008:break
 if ix in checks: print(ix,'it',it,'q',np.round(q,2),'err',round(np.linalg.norm(ep),3),round(np.linalg.norm(er),3),'limviolation',round(np.max(np.maximum(ranges[:,0]-q,q-ranges[:,1])),3))
print('last q',q)
